const mx_worley_noise_float_0 = tslFn( ( [ p_immutable, jitter_immutable, metric_immutable ] ) => {

	const metric = ShaderNode_int( metric_immutable ).toVar();
	const jitter = ShaderNode_float( jitter_immutable ).toVar();
	const p = ShaderNode_vec2( p_immutable ).toVar();
	const X = ShaderNode_int().toVar(), Y = ShaderNode_int().toVar();
	const localpos = ShaderNode_vec2( mx_floorfrac( p.x, X ), mx_floorfrac( p.y, Y ) ).toVar();
	const sqdist = ShaderNode_float( 1e6 ).toVar();

	loop( { start: - 1, end: ShaderNode_int( 1 ), name: 'x', condition: '<=' }, ( { x } ) => {

		loop( { start: - 1, end: ShaderNode_int( 1 ), name: 'y', condition: '<=' }, ( { y } ) => {

			const dist = ShaderNode_float( mx_worley_distance( localpos, x, y, X, Y, jitter, metric ) ).toVar();
			sqdist.assign( min( sqdist, dist ) );

		} );

	} );

	If( metric.equal( ShaderNode_int( 0 ) ), () => {

		sqdist.assign( sqrt( sqdist ) );

	} );

	return sqdist;

} );

